/**
 * The whole data model (docs/planning/scope-map.json, "data_model") as a Drizzle schema. After
 * changing it, run `npm run db:generate` to write the migration into drizzle/.
 *
 * Conventions: money is integer US cents; times are timestamptz; ids are uuids, generated by the
 * database or, for rows written in one batch (the engine, the demo seed), by the app. Every table
 * hangs off events with on delete cascade, so deleting a demo gala deletes everything in it.
 *
 * Additions to the scope map:
 * - holds keeps two PayPal authorization ids: void and reauthorize target the original one,
 *   capture targets the current one (a reauthorization returns a new id).
 * - bids.limit_id names the proxy limit behind a guest_max or glim bid; bid_limits gains paused_at
 *   and ended_at; amounts strictly rise per lot, so (lot_id, amount_cents) is unique.
 * - glim_transcript keeps Glim's API conversation verbatim, and chat_messages counts the tokens
 *   the daily budget needs.
 * - director_jobs (the scripted rival bids) and error_log (errors and PayPal debug ids outlive
 *   Render's 7-day logs).
 * - Glim's autopilot (docs/planning/glim-autopilot.md): glim_plans.mandate (the rules the guest
 *   confirmed), glim_actions.detail, glim_autopilot (one wake-up cursor per paddle) and
 *   glim_autopilot_runs (one row per decision run).
 * - glim_actions.source_event_log_id, so turning an engine fact into its action and event card is
 *   idempotent; chat_messages and glim_actions stamp created_at with clock_timestamp(), so rows
 *   written in one transaction keep their order in the chat and the feeds.
 * - rate_limits (the API's fixed-window counters) and heartbeats (the sweep's last beat).
 */
import { sql } from "drizzle-orm";
import {
  bigint,
  bigserial,
  boolean,
  check,
  customType,
  index,
  integer,
  jsonb,
  pgEnum,
  pgTable,
  primaryKey,
  text,
  timestamp,
  uniqueIndex,
  uuid,
  type AnyPgColumn,
} from "drizzle-orm/pg-core";

const timestamptz = (name: string) => timestamp(name, { withTimezone: true });
const createdAt = () => timestamptz("created_at").notNull().defaultNow();
/** For rows read back in insert order: now() is the transaction's start, the same for all its rows. */
const insertedAt = () => timestamptz("created_at").notNull().default(sql`clock_timestamp()`);

const bytea = customType<{ data: Buffer; driverData: Buffer }>({ dataType: () => "bytea" });

/** Uploaded lot photos live in the database (no object store), so each one is capped. */
export const MAX_LOT_PHOTO_BYTES = 1_048_576;

// ---------------------------------------------------------------------------------------------
// Enums. Domain modules keep their own string unions; tests/unit/db/schema-contract.test.ts
// checks that they match these lists.

export const eventStatus = pgEnum("event_status", ["draft", "scheduled", "live", "closed", "settling", "settled"]);
export const lotStatus = pgEnum("lot_status", ["draft", "open", "closed"]);
export const lotCategory = pgEnum("lot_category", ["dining", "experiences", "art", "wellness", "pets"]);
export const photoKind = pgEnum("photo_kind", ["illustration", "upload"]);
export const holdKind = pgEnum("hold_kind", ["paypal", "simulated"]);
export const holdStatus = pgEnum("hold_status", [
  "pending_approval",
  "authorized",
  "replaced",
  "voided",
  "captured",
  "expired",
  "denied",
  "canceled",
  "failed",
]);
export const bidSource = pgEnum("bid_source", ["guest", "guest_max", "glim", "bot"]);
export const limitOwner = pgEnum("limit_owner", ["guest_max", "glim"]);
export const glimPlanStatus = pgEnum("glim_plan_status", ["proposed", "active", "paused", "ended", "superseded"]);
export const glimPlanItemStatus = pgEnum("glim_plan_item_status", [
  "watching",
  "winning",
  "at_limit",
  "outbid_over_limit",
  "won",
  "lost",
  "skipped",
]);
export const glimActionKind = pgEnum("glim_action_kind", [
  "plan_started",
  "bid",
  "raise",
  "limit_reached",
  "lot_won",
  "lot_lost",
  "paused",
  "resumed",
  "plan_edited",
  "proposal_rejected",
  "nudge",
  "autopilot_changed",
  "autopilot_raise_prepared",
]);
export const glimDecision = pgEnum("glim_decision", ["executed", "rejected"]);
// tests/unit/db/autopilot-schema-contract.test.ts checks these against src/server/glim/autopilot/types.ts.
export const glimAutopilotOutcome = pgEnum("glim_autopilot_outcome", [
  "applied",
  "raise_prepared",
  "kept",
  "skipped",
  "stale",
  "refused",
  "failed",
  "stopped",
]);
export const glimAutopilotDecider = pgEnum("glim_autopilot_decider", ["model", "rule", "pending_raise", "none"]);
export const glimChip = pgEnum("glim_chip", ["winning", "closed", "none"]);
export const chatRole = pgEnum("chat_role", ["guest", "glim"]);
export const chatCardType = pgEnum("chat_card_type", ["plan", "event", "action", "none"]);
export const settlementStatus = pgEnum("settlement_status", ["running", "done", "done_with_errors"]);
export const settlementAction = pgEnum("settlement_action", ["capture", "void", "simulate"]);
export const settlementItemStatus = pgEnum("settlement_item_status", [
  "queued",
  "processing",
  "succeeded",
  "pending",
  "failed",
]);
export const directorJobStatus = pgEnum("director_job_status", ["queued", "running", "done", "failed", "canceled"]);
export const eventLogType = pgEnum("event_log_type", [
  "bid",
  "lot_closed",
  "event_status",
  "hold",
  "glim",
  "settlement",
]);

// ---------------------------------------------------------------------------------------------
// The auction: events, sessions, paddles, lots and their photos, favorites.

export const events = pgTable(
  "events",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    slug: text("slug").notNull().unique(),
    name: text("name").notNull(),
    charityName: text("charity_name").notNull(),
    charityEin: text("charity_ein"),
    charityIs501c3: boolean("charity_is_501c3").notNull().default(false),
    timezone: text("timezone").notNull().default("America/Los_Angeles"),
    currency: text("currency").notNull().default("USD"),
    opensAt: timestamptz("opens_at"),
    closesAt: timestamptz("closes_at").notNull(),
    status: eventStatus("status").notNull().default("draft"),
    /** PayPal's soft_descriptor, shown on the buyer's statement. */
    softDescriptor: text("soft_descriptor"),
    holdPresetsCents: integer("hold_presets_cents").array().notNull().default(sql`'{25000,50000,100000}'`),
    holdMinCents: integer("hold_min_cents"),
    holdMaxCents: integer("hold_max_cents"),
    pickupNote: text("pickup_note"),
    /** Relative to the site's origin; the projector's QR code prefixes it. */
    joinUrl: text("join_url"),
    isDemo: boolean("is_demo").notNull().default(false),
    demoExpiresAt: timestamptz("demo_expires_at"),
    templateKey: text("template_key"),
    closedAt: timestamptz("closed_at"),
    settledAt: timestamptz("settled_at"),
    createdAt: createdAt(),
  },
  (table) => [
    index("events_demo_expires_idx").on(table.demoExpiresAt).where(sql`${table.isDemo}`),
    // Live PayPal and other currencies are out of scope.
    check("events_currency_usd", sql`${table.currency} = 'USD'`),
    check("events_soft_descriptor_length", sql`char_length(${table.softDescriptor}) <= 22`),
    check("events_hold_range", sql`${table.holdMinCents} <= ${table.holdMaxCents}`),
  ],
);

export const paddles = pgTable(
  "paddles",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    eventId: uuid("event_id")
      .notNull()
      .references(() => events.id, { onDelete: "cascade" }),
    number: integer("number").notNull(),
    firstName: text("first_name").notNull(),
    lastInitial: text("last_initial"),
    /** From the PayPal payer only; guests never type it. */
    email: text("email"),
    paypalPayerId: text("paypal_payer_id"),
    isSimulated: boolean("is_simulated").notNull().default(false),
    /** The director's script for a simulated guest: budget, target lots, timing. */
    botProfile: jsonb("bot_profile"),
    createdAt: createdAt(),
  },
  (table) => [
    uniqueIndex("paddles_event_number_uq").on(table.eventId, table.number),
    check("paddles_number_positive", sql`${table.number} > 0`),
  ],
);

/** A browser's identity: no passwords, an httpOnly cookie whose hash is stored here. */
export const sessions = pgTable(
  "sessions",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    tokenHash: text("token_hash").notNull().unique(),
    eventId: uuid("event_id")
      .notNull()
      .references(() => events.id, { onDelete: "cascade" }),
    paddleId: uuid("paddle_id").references(() => paddles.id, { onDelete: "cascade" }),
    /** Organizer rights cover this session's event only. */
    isOrganizer: boolean("is_organizer").notNull().default(false),
    organizerName: text("organizer_name"),
    createdAt: createdAt(),
    lastSeenAt: timestamptz("last_seen_at").notNull().defaultNow(),
  },
  (table) => [index("sessions_event_idx").on(table.eventId), index("sessions_paddle_idx").on(table.paddleId)],
);

export const lots = pgTable(
  "lots",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    eventId: uuid("event_id")
      .notNull()
      .references(() => events.id, { onDelete: "cascade" }),
    number: integer("number").notNull(),
    /** Glim's and the ledger's name for the lot, e.g. "Chef's Table". */
    shortTitle: text("short_title").notNull(),
    title: text("title").notNull(),
    category: lotCategory("category").notNull(),
    donorName: text("donor_name"),
    description: text("description"),
    /** Null means "Needs a value"; the receipt's deductible is paid minus this. */
    estimatedValueCents: integer("estimated_value_cents"),
    valueBasis: text("value_basis"),
    startingBidCents: integer("starting_bid_cents").notNull(),
    minRaiseCents: integer("min_raise_cents").notNull(),
    /** Staggered per lot; bids at or after it are refused by the database clock. */
    closesAt: timestamptz("closes_at").notNull(),
    status: lotStatus("status").notNull().default("draft"),
    /** Null until the first bid. */
    currentBidCents: integer("current_bid_cents"),
    bidCount: integer("bid_count").notNull().default(0),
    highPaddleId: uuid("high_paddle_id").references(() => paddles.id, { onDelete: "set null" }),
    highBidSource: bidSource("high_bid_source"),
    winningPaddleId: uuid("winning_paddle_id").references(() => paddles.id, { onDelete: "set null" }),
    winningCents: integer("winning_cents"),
    closedAt: timestamptz("closed_at"),
    coverPhotoId: uuid("cover_photo_id").references((): AnyPgColumn => lotPhotos.id, { onDelete: "set null" }),
    createdAt: createdAt(),
  },
  (table) => [
    uniqueIndex("lots_event_number_uq").on(table.eventId, table.number),
    index("lots_open_closes_at_idx").on(table.closesAt).where(sql`${table.status} = 'open'`),
    check("lots_number_positive", sql`${table.number} > 0`),
    check("lots_starting_bid_positive", sql`${table.startingBidCents} > 0`),
    check("lots_min_raise_positive", sql`${table.minRaiseCents} > 0`),
    check("lots_bid_count_nonnegative", sql`${table.bidCount} >= 0`),
    check("lots_estimated_value_nonnegative", sql`${table.estimatedValueCents} >= 0`),
  ],
);

export const lotPhotos = pgTable(
  "lot_photos",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    lotId: uuid("lot_id")
      .notNull()
      .references(() => lots.id, { onDelete: "cascade" }),
    position: integer("position").notNull(),
    isCover: boolean("is_cover").notNull().default(false),
    kind: photoKind("kind").notNull(),
    /** A drawing from src/ui/drawings, for kind illustration. */
    illustrationKey: text("illustration_key"),
    data: bytea("data"),
    url: text("url"),
    mime: text("mime"),
    alt: text("alt"),
  },
  (table) => [
    index("lot_photos_lot_idx").on(table.lotId, table.position),
    check(
      "lot_photos_source",
      sql`(${table.kind} = 'illustration' and ${table.illustrationKey} is not null)
        or (${table.kind} = 'upload' and ${table.mime} is not null and (${table.data} is not null or ${table.url} is not null))`,
    ),
    check("lot_photos_data_size", sql`octet_length(${table.data}) <= ${sql.raw(String(MAX_LOT_PHOTO_BYTES))}`),
  ],
);

/** The heart on 05; Glim reads these as "lots you like". */
export const favorites = pgTable(
  "favorites",
  {
    paddleId: uuid("paddle_id")
      .notNull()
      .references(() => paddles.id, { onDelete: "cascade" }),
    lotId: uuid("lot_id")
      .notNull()
      .references(() => lots.id, { onDelete: "cascade" }),
    createdAt: createdAt(),
  },
  (table) => [primaryKey({ columns: [table.paddleId, table.lotId] }), index("favorites_lot_idx").on(table.lotId)],
);

// ---------------------------------------------------------------------------------------------
// Bidding power and bids: holds, proxy limits, bids.

export const holds = pgTable(
  "holds",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    eventId: uuid("event_id")
      .notNull()
      .references(() => events.id, { onDelete: "cascade" }),
    paddleId: uuid("paddle_id")
      .notNull()
      .references(() => paddles.id, { onDelete: "cascade" }),
    kind: holdKind("kind").notNull(),
    amountCents: integer("amount_cents").notNull(),
    status: holdStatus("status").notNull().default("pending_approval"),
    paypalOrderId: text("paypal_order_id"),
    /** The authorization PayPal created first: the target of void and reauthorize. */
    originalAuthorizationId: text("original_authorization_id"),
    /** The latest authorization (a reauthorization returns a new id): the target of capture. */
    currentAuthorizationId: text("current_authorization_id"),
    authorizedAt: timestamptz("authorized_at"),
    /** authorized_at plus PayPal's 3-day honor period. */
    honorUntil: timestamptz("honor_until"),
    /** PayPal's expiration_time for the authorization. */
    expiresAt: timestamptz("expires_at"),
    reauthorizedAt: timestamptz("reauthorized_at"),
    /** Set on the old hold when a raise authorized a new one. */
    replacedByHoldId: uuid("replaced_by_hold_id").references((): AnyPgColumn => holds.id, { onDelete: "set null" }),
    capturedCents: integer("captured_cents"),
    lastSyncedAt: timestamptz("last_synced_at"),
    paypalDebugId: text("paypal_debug_id"),
    raw: jsonb("raw"),
    createdAt: createdAt(),
  },
  (table) => [
    // A raise swaps holds in one transaction, so a paddle never has two authorized at once.
    uniqueIndex("holds_one_authorized_per_paddle_uq").on(table.paddleId).where(sql`${table.status} = 'authorized'`),
    uniqueIndex("holds_paypal_order_uq").on(table.paypalOrderId),
    index("holds_event_idx").on(table.eventId),
    index("holds_paddle_idx").on(table.paddleId),
    index("holds_original_authorization_idx").on(table.originalAuthorizationId),
    index("holds_current_authorization_idx").on(table.currentAuthorizationId),
    check("holds_amount_positive", sql`${table.amountCents} > 0`),
    check("holds_captured_nonnegative", sql`${table.capturedCents} >= 0`),
  ],
);

/** A proxy limit: the engine raises for its paddle by the minimum raise, up to max_cents. */
export const bidLimits = pgTable(
  "bid_limits",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    paddleId: uuid("paddle_id")
      .notNull()
      .references(() => paddles.id, { onDelete: "cascade" }),
    lotId: uuid("lot_id")
      .notNull()
      .references(() => lots.id, { onDelete: "cascade" }),
    maxCents: integer("max_cents").notNull(),
    owner: limitOwner("owner").notNull(),
    planItemId: uuid("plan_item_id").references((): AnyPgColumn => glimPlanItems.id, { onDelete: "set null" }),
    active: boolean("active").notNull().default(true),
    /** Paused limits keep their share of the hold but do not bid. */
    pausedAt: timestamptz("paused_at"),
    /** Outbid past its max. */
    exhaustedAt: timestamptz("exhausted_at"),
    /** Exhausted, removed, replaced, or ended by the lot's close. */
    endedAt: timestamptz("ended_at"),
    createdAt: createdAt(),
  },
  (table) => [
    uniqueIndex("bid_limits_one_active_uq").on(table.paddleId, table.lotId).where(sql`${table.active}`),
    index("bid_limits_active_lot_idx").on(table.lotId).where(sql`${table.active}`),
    index("bid_limits_paddle_idx").on(table.paddleId),
    index("bid_limits_lot_idx").on(table.lotId),
    check("bid_limits_max_positive", sql`${table.maxCents} > 0`),
    check("bid_limits_ended_iff_inactive", sql`${table.active} = (${table.endedAt} is null)`),
  ],
);

/** Accepted bids only: refusals go back to the caller, and Glim's are logged in glim_actions. */
export const bids = pgTable(
  "bids",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    lotId: uuid("lot_id")
      .notNull()
      .references(() => lots.id, { onDelete: "cascade" }),
    paddleId: uuid("paddle_id")
      .notNull()
      .references(() => paddles.id, { onDelete: "cascade" }),
    amountCents: integer("amount_cents").notNull(),
    source: bidSource("source").notNull(),
    limitId: uuid("limit_id").references(() => bidLimits.id, { onDelete: "set null" }),
    glimActionId: uuid("glim_action_id").references((): AnyPgColumn => glimActions.id, { onDelete: "set null" }),
    createdAt: createdAt(),
  },
  (table) => [
    // Also serves the lot's bid history, newest (highest) first.
    uniqueIndex("bids_lot_amount_uq").on(table.lotId, table.amountCents),
    index("bids_paddle_idx").on(table.paddleId),
    check("bids_amount_positive", sql`${table.amountCents} > 0`),
  ],
);

// ---------------------------------------------------------------------------------------------
// Glim: plans, plan items, actions, chat and the API transcript.

export const glimPlans = pgTable(
  "glim_plans",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    paddleId: uuid("paddle_id")
      .notNull()
      .references(() => paddles.id, { onDelete: "cascade" }),
    status: glimPlanStatus("status").notNull(),
    budgetCents: integer("budget_cents").notNull(),
    /** The validated model output the plan card was built from. */
    proposal: jsonb("proposal").notNull(),
    /** The model that proposed it; null for seeded plans. */
    model: text("model"),
    sourceMessageId: uuid("source_message_id").references((): AnyPgColumn => chatMessages.id, {
      onDelete: "set null",
    }),
    confirmedAt: timestamptz("confirmed_at"),
    pausedAt: timestamptz("paused_at"),
    endedAt: timestamptz("ended_at"),
    version: integer("version").notNull().default(1),
    /**
     * The rules the guest confirmed with Start bidding (GlimMandateV1, src/server/glim/mandate.ts),
     * read through mandateSchema. Null means Glim never changes this plan on its own.
     */
    mandate: jsonb("mandate"),
    createdAt: createdAt(),
  },
  (table) => [
    uniqueIndex("glim_plans_one_running_per_paddle_uq")
      .on(table.paddleId)
      .where(sql`${table.status} in ('active', 'paused')`),
    index("glim_plans_paddle_idx").on(table.paddleId),
    check("glim_plans_budget_nonnegative", sql`${table.budgetCents} >= 0`),
  ],
);

export const glimPlanItems = pgTable(
  "glim_plan_items",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    planId: uuid("plan_id")
      .notNull()
      .references(() => glimPlans.id, { onDelete: "cascade" }),
    lotId: uuid("lot_id")
      .notNull()
      .references(() => lots.id, { onDelete: "cascade" }),
    /** 1 is the lot the guest wants most. */
    priority: integer("priority").notNull(),
    maxCents: integer("max_cents").notNull(),
    status: glimPlanItemStatus("status").notNull(),
  },
  (table) => [
    uniqueIndex("glim_plan_items_plan_lot_uq").on(table.planId, table.lotId),
    index("glim_plan_items_lot_idx").on(table.lotId),
    check("glim_plan_items_priority_positive", sql`${table.priority} > 0`),
    check("glim_plan_items_max_positive", sql`${table.maxCents} > 0`),
  ],
);

/**
 * Everything Glim did or was refused, as facts with exact amounts. 07's event cards, 10's feed,
 * 11's recap, 12's "within limits" check and 14's counts are templates over these rows.
 */
export const glimActions = pgTable(
  "glim_actions",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    paddleId: uuid("paddle_id")
      .notNull()
      .references(() => paddles.id, { onDelete: "cascade" }),
    planId: uuid("plan_id").references(() => glimPlans.id, { onDelete: "cascade" }),
    lotId: uuid("lot_id").references(() => lots.id, { onDelete: "cascade" }),
    kind: glimActionKind("kind").notNull(),
    amountCents: integer("amount_cents"),
    limitCents: integer("limit_cents"),
    holdCentsAtTime: integer("hold_cents_at_time"),
    decision: glimDecision("decision").notNull(),
    rejectReason: text("reject_reason"),
    /** The rendered sentence. */
    message: text("message").notNull(),
    chip: glimChip("chip").notNull().default("none"),
    /** The rival bid a raise answered or a limit stopped at. */
    triggerBidId: uuid("trigger_bid_id").references((): AnyPgColumn => bids.id, { onDelete: "set null" }),
    /** For autopilot actions: the run, its triggers, the plan before and after, and the why. */
    detail: jsonb("detail"),
    /** The engine fact this action was written from; unique, so a replayed fact writes nothing. */
    sourceEventLogId: bigint("source_event_log_id", { mode: "number" }).references((): AnyPgColumn => eventLog.id, {
      onDelete: "set null",
    }),
    createdAt: insertedAt(),
  },
  (table) => [
    index("glim_actions_paddle_idx").on(table.paddleId, table.createdAt),
    index("glim_actions_plan_idx").on(table.planId),
    index("glim_actions_lot_idx").on(table.lotId),
    uniqueIndex("glim_actions_source_event_log_uq")
      .on(table.sourceEventLogId)
      .where(sql`${table.sourceEventLogId} is not null`),
  ],
);

/** The chat as 07 shows it. Glim's API conversation is in glim_transcript. */
export const chatMessages = pgTable(
  "chat_messages",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    paddleId: uuid("paddle_id")
      .notNull()
      .references(() => paddles.id, { onDelete: "cascade" }),
    role: chatRole("role").notNull(),
    /** Empty when the card speaks for itself. */
    text: text("text").notNull(),
    cardType: chatCardType("card_type").notNull().default("none"),
    card: jsonb("card"),
    planId: uuid("plan_id").references((): AnyPgColumn => glimPlans.id, { onDelete: "set null" }),
    /** The model that served the reply, which can be a server-side fallback model. */
    model: text("model"),
    inputTokens: integer("input_tokens"),
    outputTokens: integer("output_tokens"),
    cacheReadTokens: integer("cache_read_tokens"),
    cacheWriteTokens: integer("cache_write_tokens"),
    /** Every token the reply's calls processed; the daily budget sums these from midnight UTC. */
    tokensUsed: integer("tokens_used").notNull().default(0),
    latencyMs: integer("latency_ms"),
    error: text("error"),
    createdAt: insertedAt(),
  },
  (table) => [
    index("chat_messages_paddle_idx").on(table.paddleId, table.createdAt),
    index("chat_messages_created_idx").on(table.createdAt),
    check("chat_messages_tokens_nonnegative", sql`${table.tokensUsed} >= 0`),
  ],
);

/**
 * Glim's conversation exactly as it was sent to the API, one message per row, append-only: rows
 * are never updated or deleted (Opus 5.5 rejects an edited history that replays thinking
 * blocks). The primary key makes two concurrent turns of one paddle collide instead of fork.
 */
export const glimTranscript = pgTable(
  "glim_transcript",
  {
    paddleId: uuid("paddle_id")
      .notNull()
      .references(() => paddles.id, { onDelete: "cascade" }),
    position: integer("position").notNull(),
    /** An Anthropic MessageParam (user, assistant or mid-conversation system), verbatim. */
    message: jsonb("message").notNull(),
    chatMessageId: uuid("chat_message_id").references(() => chatMessages.id, { onDelete: "set null" }),
    createdAt: createdAt(),
  },
  (table) => [
    primaryKey({ columns: [table.paddleId, table.position] }),
    check("glim_transcript_position_nonnegative", sql`${table.position} >= 0`),
  ],
);

/**
 * Glim's autopilot for one paddle, armed when the guest confirms a plan with a mandate. The tick
 * reads the paddle's event_log rows after cursor_event_log_id, collects the facts that wake Glim
 * in reasons, and claims the paddle once due_at passes; running_since is a 60-second lease.
 */
export const glimAutopilot = pgTable(
  "glim_autopilot",
  {
    paddleId: uuid("paddle_id")
      .primaryKey()
      .references(() => paddles.id, { onDelete: "cascade" }),
    eventId: uuid("event_id")
      .notNull()
      .references(() => events.id, { onDelete: "cascade" }),
    cursorEventLogId: bigint("cursor_event_log_id", { mode: "number" }).notNull().default(0),
    /** Facts not yet claimed by a run. */
    reasons: jsonb("reasons").notNull().default(sql`'[]'::jsonb`),
    /** Facts the running (or crashed) run claimed; put back if it fails. */
    claimedReasons: jsonb("claimed_reasons").notNull().default(sql`'[]'::jsonb`),
    /** Lot ids whose closing_soon review already ran: once per lot. */
    closingReviewed: jsonb("closing_reviewed").notNull().default(sql`'[]'::jsonb`),
    dueAt: timestamptz("due_at"),
    runningSince: timestamptz("running_since"),
    lastRunAt: timestamptz("last_run_at"),
    lastModelCallAt: timestamptz("last_model_call_at"),
    attempts: integer("attempts").notNull().default(0),
    createdAt: createdAt(),
    updatedAt: timestamptz("updated_at").notNull().defaultNow(),
  },
  (table) => [
    index("glim_autopilot_due_idx").on(table.dueAt).where(sql`${table.dueAt} is not null`),
    index("glim_autopilot_event_idx").on(table.eventId),
  ],
);

/** One row per autopilot run, whatever its outcome; tokens_used counts toward the daily budget. */
export const glimAutopilotRuns = pgTable(
  "glim_autopilot_runs",
  {
    /** Generated by the app when the run starts; the row is inserted when it ends. */
    id: uuid("id").primaryKey(),
    paddleId: uuid("paddle_id")
      .notNull()
      .references(() => paddles.id, { onDelete: "cascade" }),
    eventId: uuid("event_id")
      .notNull()
      .references(() => events.id, { onDelete: "cascade" }),
    planId: uuid("plan_id").references(() => glimPlans.id, { onDelete: "set null" }),
    actionId: uuid("action_id").references(() => glimActions.id, { onDelete: "set null" }),
    triggers: jsonb("triggers").notNull(),
    outcome: glimAutopilotOutcome("outcome").notNull(),
    decidedBy: glimAutopilotDecider("decided_by").notNull(),
    /** The model called, or null when the run made no model call. */
    model: text("model"),
    brief: text("brief"),
    error: text("error"),
    decision: jsonb("decision"),
    issues: jsonb("issues"),
    planVersionBefore: integer("plan_version_before"),
    planVersionAfter: integer("plan_version_after"),
    latencyMs: integer("latency_ms"),
    inputTokens: integer("input_tokens"),
    outputTokens: integer("output_tokens"),
    cacheReadTokens: integer("cache_read_tokens"),
    cacheWriteTokens: integer("cache_write_tokens"),
    tokensUsed: integer("tokens_used").notNull().default(0),
    startedAt: timestamptz("started_at").notNull().defaultNow(),
    finishedAt: timestamptz("finished_at"),
  },
  (table) => [
    index("glim_autopilot_runs_paddle_idx").on(table.paddleId, table.startedAt),
    index("glim_autopilot_runs_event_idx").on(table.eventId, table.startedAt),
    index("glim_autopilot_runs_started_idx").on(table.startedAt),
    check("glim_autopilot_runs_tokens_nonnegative", sql`${table.tokensUsed} >= 0`),
  ],
);

// ---------------------------------------------------------------------------------------------
// Settlement: charging winners, releasing everyone else, receipts, PayPal webhooks.

export const settlements = pgTable(
  "settlements",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    // One per event: PayPal refuses a reused invoice_id, so a paddle can be charged only once.
    eventId: uuid("event_id")
      .notNull()
      .unique()
      .references(() => events.id, { onDelete: "cascade" }),
    status: settlementStatus("status").notNull().default("running"),
    startedBySessionId: uuid("started_by_session_id").references(() => sessions.id, { onDelete: "set null" }),
    startedAt: timestamptz("started_at").notNull().defaultNow(),
    finishedAt: timestamptz("finished_at"),
    toChargeCents: integer("to_charge_cents").notNull().default(0),
    toReleaseCents: integer("to_release_cents").notNull().default(0),
    winners: integer("winners").notNull().default(0),
    nonWinners: integer("non_winners").notNull().default(0),
    /** The checks 12 ran before charging, with their results. */
    checks: jsonb("checks"),
  },
  (table) => [
    check(
      "settlements_totals_nonnegative",
      sql`${table.toChargeCents} >= 0 and ${table.toReleaseCents} >= 0 and ${table.winners} >= 0 and ${table.nonWinners} >= 0`,
    ),
  ],
);

export const settlementItems = pgTable(
  "settlement_items",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    settlementId: uuid("settlement_id")
      .notNull()
      .references(() => settlements.id, { onDelete: "cascade" }),
    paddleId: uuid("paddle_id")
      .notNull()
      .references(() => paddles.id, { onDelete: "cascade" }),
    holdId: uuid("hold_id")
      .notNull()
      .references(() => holds.id, { onDelete: "cascade" }),
    /** capture a winner, void a real hold that won nothing, or settle a simulated guest in the database. */
    action: settlementAction("action").notNull(),
    amountCents: integer("amount_cents").notNull().default(0),
    releasedCents: integer("released_cents").notNull().default(0),
    status: settlementItemStatus("status").notNull().default("queued"),
    /** The PayPal-Request-Id of the latest attempt; retries reuse it. */
    paypalRequestId: text("paypal_request_id"),
    /** The receipt's transaction ID. */
    paypalCaptureId: text("paypal_capture_id"),
    paypalDebugId: text("paypal_debug_id"),
    errorCode: text("error_code"),
    attempts: integer("attempts").notNull().default(0),
    /** Backoff: the queue claims an item only once this has passed. */
    nextAttemptAt: timestamptz("next_attempt_at"),
    createdAt: createdAt(),
    completedAt: timestamptz("completed_at"),
  },
  (table) => [
    uniqueIndex("settlement_items_settlement_paddle_uq").on(table.settlementId, table.paddleId),
    index("settlement_items_hold_idx").on(table.holdId),
    index("settlement_items_paddle_idx").on(table.paddleId),
    check(
      "settlement_items_amounts_nonnegative",
      sql`${table.amountCents} >= 0 and ${table.releasedCents} >= 0 and ${table.attempts} >= 0`,
    ),
  ],
);

/** A snapshot taken at capture (or at the void), so a receipt never changes after it is issued. */
export const receipts = pgTable(
  "receipts",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    eventId: uuid("event_id")
      .notNull()
      .references(() => events.id, { onDelete: "cascade" }),
    paddleId: uuid("paddle_id")
      .notNull()
      .references(() => paddles.id, { onDelete: "cascade" }),
    /** e.g. "1107-142": the event's date and the paddle number. */
    number: text("number").notNull(),
    issuedAt: timestamptz("issued_at").notNull().defaultNow(),
    holdCents: integer("hold_cents").notNull(),
    holdAuthorizedAt: timestamptz("hold_authorized_at"),
    paidCents: integer("paid_cents").notNull(),
    releasedCents: integer("released_cents").notNull(),
    /** max(0, paid minus estimated value), summed over the lines. */
    deductibleCents: integer("deductible_cents").notNull(),
    paypalCaptureId: text("paypal_capture_id"),
    statementDescriptor: text("statement_descriptor"),
    /** One entry per lot: lot, won_at, paid, estimated value, deductible, bid_by, limit. */
    lines: jsonb("lines").notNull().default(sql`'[]'::jsonb`),
    glimRecap: jsonb("glim_recap"),
    emailedAt: timestamptz("emailed_at"),
  },
  (table) => [
    uniqueIndex("receipts_event_paddle_uq").on(table.eventId, table.paddleId),
    uniqueIndex("receipts_event_number_uq").on(table.eventId, table.number),
    index("receipts_paddle_idx").on(table.paddleId),
    check(
      "receipts_amounts_nonnegative",
      sql`${table.holdCents} >= 0 and ${table.paidCents} >= 0 and ${table.releasedCents} >= 0 and ${table.deductibleCents} >= 0`,
    ),
  ],
);

/** Verified deliveries only, stored once per PayPal event id (PayPal retries up to 25 times). */
export const paypalWebhookEvents = pgTable(
  "paypal_webhook_events",
  {
    paypalEventId: text("paypal_event_id").primaryKey(),
    eventType: text("event_type").notNull(),
    resourceType: text("resource_type"),
    resourceId: text("resource_id"),
    verified: boolean("verified").notNull(),
    payload: jsonb("payload").notNull(),
    receivedAt: timestamptz("received_at").notNull().defaultNow(),
    processedAt: timestamptz("processed_at"),
    error: text("error"),
  },
  (table) => [
    index("paypal_webhook_events_resource_idx").on(table.resourceId),
    index("paypal_webhook_events_unprocessed_idx").on(table.receivedAt).where(sql`${table.processedAt} is null`),
  ],
);

// ---------------------------------------------------------------------------------------------
// Live updates, the director and errors.

/**
 * Every change the live layer shows, written in the same transaction as the change. The id is
 * the stream position (SSE Last-Event-ID); paddle_id null is the event's public channel.
 */
export const eventLog = pgTable(
  "event_log",
  {
    id: bigserial("id", { mode: "number" }).primaryKey(),
    eventId: uuid("event_id")
      .notNull()
      .references(() => events.id, { onDelete: "cascade" }),
    paddleId: uuid("paddle_id").references(() => paddles.id, { onDelete: "cascade" }),
    type: eventLogType("type").notNull(),
    payload: jsonb("payload").notNull(),
    createdAt: createdAt(),
  },
  (table) => [
    index("event_log_event_id_idx").on(table.eventId, table.id),
    index("event_log_paddle_idx").on(table.paddleId).where(sql`${table.paddleId} is not null`),
  ],
);

/** The scripted director's queue (rival bids, background bots), claimed with FOR UPDATE SKIP LOCKED. */
export const directorJobs = pgTable(
  "director_jobs",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    eventId: uuid("event_id")
      .notNull()
      .references(() => events.id, { onDelete: "cascade" }),
    kind: text("kind").notNull(),
    payload: jsonb("payload").notNull().default(sql`'{}'::jsonb`),
    runAt: timestamptz("run_at").notNull(),
    status: directorJobStatus("status").notNull().default("queued"),
    attempts: integer("attempts").notNull().default(0),
    lockedAt: timestamptz("locked_at"),
    completedAt: timestamptz("completed_at"),
    lastError: text("last_error"),
    createdAt: createdAt(),
  },
  (table) => [
    index("director_jobs_due_idx").on(table.runAt).where(sql`${table.status} = 'queued'`),
    index("director_jobs_event_idx").on(table.eventId),
    check("director_jobs_attempts_nonnegative", sql`${table.attempts} >= 0`),
  ],
);

/**
 * Fixed-window counters behind the API's rate limits (src/server/api/rate-limit.ts). In Postgres so
 * a limit survives a deploy and holds across overlapping instances. Keys carry a keyed hash of the
 * client's address, never the address itself. The sweep deletes old windows.
 */
export const rateLimits = pgTable(
  "rate_limits",
  {
    key: text("key").notNull(),
    windowStart: timestamptz("window_start").notNull(),
    count: integer("count").notNull(),
  },
  (table) => [
    primaryKey({ columns: [table.key, table.windowStart] }),
    index("rate_limits_window_idx").on(table.windowStart),
  ],
);

/** The latest beat of each background job, e.g. "sweep"; monitoring reads how old it is. */
export const heartbeats = pgTable("heartbeats", {
  name: text("name").primaryKey(),
  beatAt: timestamptz("beat_at").notNull().defaultNow(),
  detail: jsonb("detail"),
});

/** Errors worth keeping past Render's 7 days of logs. Rows outlive the demo they came from. */
export const errorLog = pgTable(
  "error_log",
  {
    id: bigserial("id", { mode: "number" }).primaryKey(),
    /** The area that failed: paypal, glim, engine, settlement, webhook, cron. */
    source: text("source").notNull(),
    code: text("code"),
    message: text("message").notNull(),
    eventId: uuid("event_id").references(() => events.id, { onDelete: "set null" }),
    paddleId: uuid("paddle_id").references(() => paddles.id, { onDelete: "set null" }),
    paypalDebugId: text("paypal_debug_id"),
    detail: jsonb("detail"),
    createdAt: createdAt(),
  },
  (table) => [
    index("error_log_created_idx").on(table.createdAt),
    index("error_log_event_idx").on(table.eventId),
    index("error_log_paddle_idx").on(table.paddleId),
  ],
);
